// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Why use fixed-size chunks rather than content-defined chunking, and when would you switch?", "Fixed 4 MB chunks are simple, fast to compute and easy to index. They work well for files that are appended to or rewritten in place. Their weakness is insertion: add one byte near the start and every later boundary shifts, so every later hash changes and almost the whole file uploads again. Content-defined chunking runs a rolling hash, such as Rabin or FastCDC, over a sliding window and cuts wherever the hash matches a pattern. Boundaries then follow the content, so an insertion changes only one or two chunks. The costs are variable chunk sizes, more client CPU, and the need for minimum and maximum chunk bounds. I would start with fixed-size chunks and move to CDC only if measurements show real dedup gains for documents or backup-style workloads."),
    s(5, "Why use optimistic concurrency with a base revision instead of locking files during edits?", "Locks need the holder to stay reachable. A laptop that goes offline would hold its lock forever, or a lease would expire in the middle of an edit. Most files are never edited by two people at the same moment, so optimistic concurrency suits this workload. The client sends the revision it edited from, and the commit does a compare-and-set against the file's current revision inside the metadata transaction. If they match, the new version becomes current. If not, another writer won, and we save the upload as a conflicted copy instead of overwriting anything. The common case costs almost nothing, and the scheme stays correct during network partitions. Advisory locks can be added for particular apps, but they are a convenience, not the safety mechanism."),
    s(5, "Walk me through the core tables of the metadata service.", "The core tables are:\n- namespaces: id, owner, type (user root or shared folder).\n- file_entries: namespace_id, file_id, parent_id, name, is_folder, current_revision, deleted_at.\n- file_versions: file_id, revision, size, content_hash, author, created_at, ordered chunk list.\n- chunks: hash, size, storage key, refcount, state.\n- journal: namespace_id, seq, file_id, operation, revision.\n- acl: resource_id, principal, role.\n- upload_sessions: upload_id, user, expected hashes, expiry.\n\nThe journal key is (namespace_id, seq) and the versions key is (file_id, revision). A unique constraint on (namespace_id, parent_id, name) for live entries stops duplicate names. Everything except the chunk index is sharded by namespace_id, so a commit stays a single-shard transaction."),
    s(4, "How would you shard the metadata service, and what breaks with a hot namespace?", "I would shard by namespace ID. Each user root and each shared folder is its own namespace. A commit touches the file entry, the version row and the journal of one namespace, so it is a local transaction with no two-phase commit. The journal sequence comes from a per-namespace counter updated in that same transaction. The chunk index is different: it is keyed by hash, so I would shard it by hash prefix, which spreads load evenly. A huge team folder can outgrow one shard or serialize on its counter. Options are moving it to a dedicated shard or splitting large subtrees into child namespaces. Moves between namespaces become a multi-step, idempotent saga with a durable move record."),
    s(4, "Give me a back-of-envelope estimate for this system.", "I would state my assumptions out loud, because they are illustrative, not real figures. Assume 100 million users, 10 percent active daily, each changing 20 files a day:\n- Commits: 200 million a day, about 2,300 per second on average. I would plan for a peak several times higher.\n- Upload bytes: if the average new data after dedup is 1 MB per commit, that is roughly 200 TB a day.\n- Metadata: each version row is a few hundred bytes plus its chunk list, so it is tiny next to the blobs.\n- Connections: concurrent notification connections roughly equal the number of online devices.\n\nThe takeaway is that a sharded database handles metadata QPS. Object storage bandwidth and capacity dominate cost, and reads such as list-changes and downloads outnumber writes."),
    s(4, "How do cursors work, and what happens when the journal is compacted past a client's cursor?", "A cursor is an opaque, ideally signed, token that encodes the namespace and the last sequence number the client applied. list-changes returns entries after that number, up to a page limit, along with a new cursor and a has_more flag. The journal cannot grow forever, so old entries are compacted to keep only the latest state per file, or are dropped after a retention window. If a client presents a cursor older than retained history, the server returns a reset error. The client then does a full paged listing and reconciles it against its local database by revision and hash. It must not delete or overwrite local edits that have not synced yet; those are uploaded with their base revision as usual."),
    s(5, "What privacy risk does cross-user deduplication create, and how do you mitigate it?", "If the server tells a client that a chunk already exists, the client learns that someone stored that exact content. This is a confirmation-of-file attack. An attacker can test guesses, such as a known document with one field varied, and see which variant skips upload. A second risk is a client that knows only a hash claiming to own the content. Mitigations:\n- Restrict dedup to within a user or organization.\n- Do dedup server-side only, where the client always uploads and the server stores the chunk once silently. This trades away bandwidth savings.\n- Never let knowing a hash grant access. A commit may only reference chunks the user actually uploaded or already owns. Many designs restrict cross-user dedup for these reasons."),
    s(4, "How would you handle encryption at rest and key management for chunks and metadata?", "All traffic uses TLS. Chunks are encrypted at rest with envelope encryption: data keys encrypt the chunks, and master keys held in a KMS wrap the data keys. Master keys can then rotate without re-encrypting every chunk. File names and paths are sensitive too, so the metadata store is also encrypted. Key scope is a trade-off. Per-user keys give strong isolation and allow crypto-shredding, where destroying a user's key makes their data unreadable, which helps with deletion requests. However, per-user keys block cross-user dedup. Convergent encryption, where the key is derived from the chunk content, restores dedup but brings back the confirmation-of-file risk. Access to the KMS is tightly audited and restricted to the storage services."),
    s(4, "Why hand clients signed URLs for chunk downloads, and what are the risks?", "Signed URLs let bytes flow straight from object storage or a CDN to the device, so application servers never stream file data and scale only with metadata traffic. The flow is: the metadata service checks the ACL first, then signs a URL scoped to one chunk object, GET only, with an expiry of a few minutes. The risk is leakage. Anyone holding the URL can fetch that chunk until it expires, and an issued URL cannot be recalled after a permission is revoked. Short TTLs bound that exposure. Scoping each URL to a single chunk limits the damage. Chunk keys are hashes, so they are not guessable, but security must come from the signature, not obscurity. Clients also verify the hash of whatever they download."),
    s(4, "Design the notification service that tells devices to sync.", "Devices hold a WebSocket or long-poll connection to a fleet of gateways. Each gateway records which namespaces its connections subscribe to in a shared registry. A commit writes an outbox row in the same transaction as the journal entry. A relay publishes that row to a message bus. Fan-out workers look up which gateways hold subscribers and push a tiny hint, such as the namespace and latest sequence number. Delivery can be lossy, because a device always calls list-changes on reconnect and periodically, so a dropped hint only delays sync. Bursts are coalesced, so a hundred commits in one second produce one hint. Gateways are stateful, so deploys drain them gradually and clients reconnect with jittered backoff."),
    s(4, "What happens if a client crashes after uploading chunks but before committing the version?", "The chunks sit in object storage, but no version references them yet. Nothing is visible to other devices, because the commit is the only point at which a version exists, so nobody sees a half-uploaded file. The upload session records the received chunks with an expiry. When the client restarts, it resumes with the same upload ID, finds that everything is already received, and commits. If the session expires first, those chunks are orphans. Garbage collection removes chunks that have zero references and are older than a grace period. That grace period matters: dedup may have pointed another in-flight session at the same chunk, so GC must never delete a chunk that a live session might still commit."),
    s(5, "Describe the race between deduplication and garbage collection, and how you prevent data loss.", "The dangerous sequence is:\n1. A chunk's refcount drops to zero.\n2. A new upload checks the index, sees the chunk exists, and skips uploading it.\n3. GC deletes the chunk.\n4. The commit then references a missing chunk, and that version is unreadable.\n\nTo prevent it, GC first marks the chunk tombstoned, so dedup checks treat it as absent. GC then waits a grace period longer than the maximum upload session lifetime, rechecks that the refcount is still zero, and only then deletes. The commit transaction verifies every referenced chunk is present and not tombstoned, and increments refcounts atomically. If verification fails, the client is told to re-upload. A periodic mark-and-sweep audit catches refcount drift."),
    s(4, "How would you cache ACL decisions without making revocation unsafe?", "Resolving effective permission means walking ancestor folders, which is expensive, so I would cache computed results by user and resource, tagged with an ACL version. Any sharing change on a folder bumps the version for that subtree and publishes an invalidation, so stale entries are ignored. For safety, the high-risk paths re-check the authoritative store or use a very short TTL: committing a version, issuing a signed URL, and adding a namespace subscription. On revocation, the namespace is removed from the user's subscriptions, and their client deletes the local copy on its next sync. I would be honest in the interview that bytes already downloaded to a former collaborator's device cannot be recalled; revocation only protects future access."),
    s(4, "How do you make renaming or moving a folder with 100,000 files cheap?", "If every file stored its full path, a folder rename would rewrite 100,000 rows. Instead, each entry stores a parent_id, and paths are computed when needed. A move then updates one row, the folder's parent and name. It also writes one journal entry, and clients apply it by re-parenting locally. The transaction must check for cycles, rejecting a move of a folder into its own descendant. It must also check name uniqueness in the destination. Inherited permissions change automatically because resolution walks the new ancestors, though ACL caches for that subtree need invalidating. Moving across namespaces, for example into a shared folder, is heavier. It copies metadata into the target namespace, reuses chunks by reference, and removes the source, all as an idempotent saga."),
    s(3, "Why create a conflicted copy rather than automatically merging concurrent edits?", "The sync service treats files as opaque bytes. It does not understand spreadsheet, image or database formats, and merging their bytes would very likely corrupt them. A conflicted copy keeps both versions intact, so no committed work is lost or silently overwritten, and the user decides which to keep. The copy's name includes the author's device or name and the date, so it is easy to find. Real-time co-editing products use a different model: operational transformation or CRDTs on a structured document, not whole-file sync. A sync product could later add format-aware merging for plain text, but the safe default is to preserve both sides."),
    s(4, "How does the client apply changes so that a crash mid-sync never corrupts local state?", "The client keeps a local database, often SQLite, holding its cursor and, for each file, the path, synced revision and content hash. It applies entries in sequence order. For each one:\n1. It skips the entry if the local revision is already equal or newer, which makes reprocessing idempotent.\n2. If the local file's hash differs from the last synced hash, the user edited it, so the client must not overwrite. It keeps the local edit and uploads it with its base revision, which triggers the normal conflict path.\n3. Otherwise it downloads missing chunks, writes to a temp file, verifies the hash, atomically renames it into place, and updates the database.\n\nThe cursor advances only after those writes are durable, so a crash means replaying a few entries, which is harmless."),
    s(3, "A user edits one byte in a 2 GB file. How much gets uploaded, and can you do better?", "With fixed 4 MB chunks, only the chunk containing that byte changes. The client re-hashes the file, finds one new hash, and uploads about 4 MB instead of 2 GB. The new version reuses every other chunk by reference. To do better, we could compute a binary delta inside that chunk against the previous version, rsync-style, and send only the difference. The server or a worker then rebuilds the chunk. That saves bandwidth at the cost of CPU and complexity, which may matter on mobile. Compressing chunks before upload also helps for compressible data. Note that re-hashing 2 GB on the client is itself a cost; storing per-chunk modification metadata can help skip unchanged regions."),
    s(4, "How do you guarantee that a committed version is never lost?", "The commit is acknowledged only after two things hold. First, every referenced chunk is confirmed durable in object storage, which replicates across failure zones. Second, the metadata transaction is synchronously replicated to a quorum or a standby in another zone. Beyond that:\n- Metadata has backups and point-in-time recovery, and the journal makes changes replayable.\n- Background scrubbing re-reads chunks, verifies hashes and repairs from replicas.\n- Cross-region disaster recovery is usually asynchronous, so the recovery point is not zero. Zero loss across regions requires synchronous cross-region commits, which add latency.\n- Version history and trash protect against user mistakes, and GC never deletes anything a retained version still references."),
    s(3, "How would the system help a user recover from ransomware that encrypted their synced files?", "The ransomware's changes sync as ordinary new versions, but old versions are retained, so the original data is still there. The journal shows exactly which files changed and when. We can offer a bulk restore of a namespace to a point in time just before the attack. That restore creates new versions pointing at the old chunk lists, so it rewrites no history and costs almost no storage. Detection helps too: a burst of many files rewritten within minutes, often with high-entropy content or renamed extensions, can trigger an alert and pause sync from that device. The retention window must be long enough for users to notice the attack."),
    s(4, "What metrics and alerts would you put on this system?", "Key metrics:\n- Server side: commit latency and error rate, conflict rate, upload resume and abandonment rate, list-changes latency, notification delivery lag, GC backlog, and object storage error rates.\n- End to end: sync lag, the time from a commit to another device applying it, measured through client telemetry.\n- Integrity: refcount audit mismatches, hash verification failures, and any download that hits a missing chunk. That last one should be zero and should page immediately, because it means data loss.\n- Security: ACL denial spikes and unusual share or download patterns.\n\nI would define SLOs on commit success, commit latency and sync lag at a high percentile."),
    s(3, "How would you enforce storage quotas and limit abuse?", "Quota should count the logical bytes of versions a user owns, not the physical bytes after dedup. Otherwise usage would depend on what other people store, which users cannot see or predict. The upload session reserves quota when it opens, so parallel uploads cannot overshoot, and the commit finalizes the reservation. Retained old versions and trash may or may not count, depending on product policy. Per-user and per-device rate limits on commits and list-changes protect shared shards. Public links can be abused for malware distribution, so they need download rate limits, scanning and a takedown path. Because of dedup, takedown removes the offending versions, and chunks are then freed only through normal refcounting."),
    s(4, "Why must the server recompute chunk hashes instead of trusting the client?", "If the server trusted the client's claimed hash, a malicious client could upload garbage labelled with the hash of a popular chunk. With deduplication, every other file referencing that hash would then read the garbage, which is index poisoning. The upload service therefore computes SHA-256 over the received bytes and rejects any mismatch before the chunk enters the index. It also stores an object storage checksum for transport integrity. On download, the client verifies each chunk's hash, and the version records a whole-file hash for end-to-end verification. Background scrubbing re-verifies chunks at rest. These checks together catch bugs, bit rot and attacks."),
    s(3, "What makes the desktop file-system watcher hard to get right?", "Watcher events are unreliable and messy:\n- They are coalesced or dropped. Linux inotify can overflow its queue, and macOS FSEvents batches changes. The agent therefore needs periodic rescans that compare size, mtime and, when in doubt, hashes.\n- Apps often write a temp file and then rename it, or write a file in several bursts. The agent debounces until the file is stable and ignores known temp patterns.\n- Files may be locked or still being written, so the agent retries later.\n- Cross-platform problems include case-insensitive file systems, characters that are invalid on Windows, path length limits, and symlinks. All of these can cause name collisions that must be resolved without losing data."),
    s(3, "After a regional outage, millions of clients reconnect at once. How do you avoid a thundering herd?", "On the client side, reconnects and list-changes retries use exponential backoff with full jitter, and they honour Retry-After headers. On the server side, admission control and load shedding protect the metadata shards, with commits prioritized over background polling. Notification gateways come back gradually rather than all at once. list-changes must stay cheap: it is an index range scan on namespace and sequence, with page limits. Devices that are far behind simply catch up over several pages. Feature flags can temporarily slow down non-essential work such as thumbnails or GC. We would rehearse this recovery scenario in game days, not discover it during a real outage."),
    s(4, "A shared folder has thousands of members. How do you avoid writing every change into every member's journal?", "Copying each change into each member's personal journal would turn one commit into thousands of writes. Instead, the shared folder is its own namespace with its own journal. A commit writes once. Each client tracks a separate cursor for every namespace it has mounted. When someone joins the share, their root namespace gets a single mount entry, and their client then syncs the shared namespace from the start. Only notification fan-out scales with membership, and it is lightweight, coalesced and lossy. Permission checks happen against the shared folder's ACL. When a member is removed, an unmount entry is written and their subscription is dropped."),
    s(3, "How do retention, legal holds and account deletion requests interact?", "Account deletion removes the user's metadata, decrements the refcounts of their chunks, and lets GC delete chunks nobody else references. Crypto-shredding per-user keys, where used, makes any remaining copies unreadable quickly. Chunks shared with other users through dedup remain, because those users still own that content. A legal hold is a flag on an account or resource that purge and GC jobs must check before deleting any version or trash entry. Holds override normal retention. Backups expire on their own schedule, so the deletion policy should state how long data may persist in backups. Every purge is logged for audit."),
    s(3, "What would end-to-end encryption change in this design?", "With end-to-end encryption, clients encrypt chunks with keys the server never sees. That removes cross-user dedup and server-side previews, full-text search, thumbnails and malware scanning. It also means lost keys cannot be recovered by the provider. Sharing requires wrapping the folder key with each recipient's public key. Revoking someone means rotating keys for future versions, while anything they already downloaded stays readable to them. The server still sees metadata such as sizes, timing, and possibly names unless those are encrypted too. Conflict detection still works, because revisions are plain metadata. A common compromise is to offer E2EE as an optional vault for sensitive folders."),
    s(3, "How would you support files-on-demand so a laptop does not download everything?", "The client still applies the full journal, but it creates placeholder files using OS integration: the Cloud Files API on Windows and File Provider on macOS. Placeholders carry name, size and dates but no content. When a user or app opens one, the OS calls the client, which fetches the needed chunks through signed URLs and hydrates the file. Users can pin folders to keep them fully downloaded offline. Unpinned content can be evicted by least-recently-used order when disk space runs low. Mobile apps typically default to on-demand. A local edit to a hydrated file uploads normally with its base revision."),
    s(3, "How would you test a sync engine to be confident it never loses data?", "I would build a deterministic simulation that runs clients, server and network in one process with a seeded random scheduler. It injects drops, reordering, crashes and clock skew while random users create, edit, move and delete files. After each run it checks invariants:\n- No committed version is ever lost.\n- No edit is overwritten without a matching base revision.\n- All devices converge to the same tree.\n- Permissions are never bypassed.\n\nFailing seeds replay exactly, which makes bugs debuggable. Property-based tests cover the planner logic. Before release, a new engine can shadow-run against the old one and compare decisions, then roll out in stages with telemetry on conflicts and errors."),
    s(4, "A new user installs the app with a million existing local files. How do you handle the first sync?", "The client hashes files in the background with CPU and disk throttling, so the laptop stays usable. It uploads small files first, because they give quick visible progress. Dedup checks are batched, sending hundreds of hashes per request, and only missing chunks upload, with bounded parallelism and resumable sessions. Commits are batched too, while each file still gets its own version and base-revision check. On the server, bulk APIs, per-account rate limits and quota reservations stop one huge account from monopolizing a shard. Progress is checkpointed in the local database, so a restart resumes instead of re-hashing everything."),
  ],
  objective: [
    o(5, "Why does the client send the base revision it edited from along with the hash list?", ["So the server can detect a concurrent edit and avoid overwriting it","So the server can compress the new chunks","So the server can choose which object storage region to use","So the server can skip ACL checks for the owner"], 0, "The commit is a compare-and-set against the current revision. A mismatch means someone else committed first, so the upload becomes a conflicted copy instead of an overwrite."),
    o(5, "At commit time, the client's base revision is no longer the latest. What should the metadata service do?", ["Overwrite the latest version, because the last writer wins","Reject the upload and delete its chunks","Save the upload as a conflicted copy","Merge the two versions byte by byte"], 2, "A conflicted copy preserves both edits, so nothing committed is lost or silently overwritten."),
    o(5, "When is the metadata service allowed to commit the new file version?", ["As soon as the first chunk is received","Only after all referenced chunks are durably stored","Before upload starts, to reserve the revision number","After all other devices have downloaded the file"], 1, "Committing before the chunks are durable could publish a version whose data does not exist, which would break the never-lose-a-version guarantee."),
    o(4, "With fixed 4 MB chunking, one byte is inserted at the start of a 100 MB file. What happens?", ["Only the first chunk changes","No chunks change, because SHA-256 ignores offsets","Only the last chunk changes","Essentially every chunk boundary shifts, so nearly all chunk hashes change"], 3, "Fixed boundaries are tied to byte offsets, so an insertion shifts all later content across boundaries. Content-defined chunking avoids this."),
    o(4, "Why does the push notification carry only a hint and no file data?", ["Push protocols cannot carry binary data","Notifications are lossy, and the change journal via list-changes is the source of truth","File data must be encrypted, and hints need no encryption","Hints are cheaper to store in object storage"], 1, "Devices always reconcile through list-changes with their cursor, so a lost hint only delays sync. Keeping data out of pushes also keeps permission checks in one place."),
    o(4, "What is the main purpose of the per-namespace monotonically increasing sequence number in the change journal?", ["To count the files in the namespace","To generate chunk hashes","To give changes a total order that devices can resume from with a cursor","To measure storage quota"], 2, "A cursor holds the last sequence number applied, so a device can fetch exactly the later entries, in order, and replay them."),
    o(4, "Which shard key best keeps a commit within a single-shard transaction?", ["Namespace ID","Chunk hash","Upload timestamp","Device ID"], 0, "The file entry, version and journal rows of one commit all belong to one namespace, so sharding by namespace keeps the transaction local."),
    o(4, "Why should the upload service recompute SHA-256 on the received bytes?", ["To speed up the upload","Because clients cannot compute SHA-256","To pick the storage tier","To stop a malicious client from poisoning the dedup index with wrong data under a valid hash"], 3, "With dedup, a fake chunk stored under a popular hash would corrupt every file that references that hash."),
    o(4, "Which attack is a key risk of client-visible cross-user deduplication?", ["SQL injection","Confirmation-of-file, learning whether specific content already exists on the service","Clickjacking","DNS rebinding"], 1, "If uploads skip chunks that already exist, a client can infer that someone else stored that exact content."),
    o(4, "Which property should a chunk download signed URL have?", ["Short expiry and scope limited to a single object and the GET method","No expiry, so clients can cache it forever","Scope to the user's whole bucket","Reuse across all users for CDN efficiency"], 0, "An issued URL cannot be revoked, so a short TTL and narrow scope limit exposure if it leaks or permission changes."),
    o(4, "When is it safe to physically delete a chunk?", ["Immediately when a file is moved to trash","When its refcount is zero, it has been tombstoned, and a grace period longer than any upload session has passed","When the chunk is older than 30 days","When the file's owner logs out"], 1, "The tombstone and grace period prevent the race where an in-flight upload has deduplicated against a chunk that GC is about to delete."),
    o(4, "Sharing a folder with thousands of members should avoid which design?", ["Making the shared folder its own namespace","Keeping a separate cursor per mounted namespace","Copying every change into each member's personal journal","Coalescing notifications"], 2, "Per-member copies turn one commit into thousands of writes. A separate shared namespace writes each change once."),
    o(4, "Why must the new file version and its journal entry be written in the same transaction?", ["To reduce storage cost","So a version can never exist without a journal entry, which would leave devices unaware of it, and vice versa","Because the journal stores the chunk bytes","To avoid needing ACL checks"], 1, "Atomicity guarantees every committed change is ordered and discoverable through list-changes."),
    o(4, "A folder is shared with you, and you open a file three levels below it. What decides your access?", ["Only the file's own ACL entry","Only the root folder of the owner's drive","The ACL of the folder you last opened","Your effective permission from explicit grants plus those inherited from ancestor folders"], 3, "Permissions on a shared parent folder flow down to its descendants, so resolution walks the ancestors."),
    o(3, "What makes renaming a folder that contains many files a cheap operation?", ["Storing a full path string on every file","Storing parent_id pointers and computing paths when needed","Re-uploading the folder's chunks","Locking the whole namespace"], 1, "With parent pointers, a rename updates one row and one journal entry instead of every descendant."),
    o(3, "A client's cursor is older than the journal's retained history. What should happen?", ["The server silently returns an empty list","The client deletes all local files","The server returns a reset, and the client does a full listing and reconciles without discarding unsynced local edits","The client resumes from sequence zero of a new journal"], 2, "A full resync restores correctness, and preserving local unsynced edits avoids data loss."),
    o(3, "How does a resumable upload recover after a network drop?", ["The client restarts the whole file from byte zero","The client asks the session which chunks were received and uploads only the rest","The server guesses the missing chunks","The client switches to a new upload ID and discards the old one"], 1, "Idempotent chunk uploads under a stable upload ID let the client query progress and continue from there."),
    o(3, "What reliably connects a committed transaction to the notification pipeline?", ["Sending the push before the transaction commits","Writing an outbox row in the same transaction and relaying it to a message bus","Having clients poll object storage","Cron-scanning all files every hour"], 1, "The transactional outbox ensures an event exists if and only if the commit happened, with no dual-write gap."),
    o(3, "What does convergent encryption enable, and at what cost?", ["Perfect forward secrecy, at the cost of no dedup","Faster uploads, at the cost of weaker TLS","Dedup of encrypted chunks, at the cost of reintroducing the confirmation-of-file risk","Smaller chunks, at the cost of more metadata"], 2, "Deriving the key from the content makes identical plaintext produce identical ciphertext, which allows dedup but also allows guessing."),
    o(3, "In what order should a device apply entries returned by list-changes?", ["Strictly in increasing sequence number","In any order, applied in parallel","Largest files first","Alphabetically by path"], 0, "Operations such as create, move and delete depend on order, and applying them in sequence order makes the result deterministic and replayable."),
    o(3, "When should a commit be acknowledged to the client?", ["When the request reaches the load balancer","When the version is written to the primary's in-memory cache","When a notification has been sent","When the metadata transaction is durably replicated and all chunks are confirmed stored"], 3, "Acknowledging earlier could lose a committed version if a node fails."),
    o(3, "Over time, chunk refcounts may drift because of bugs. What is a standard safeguard?", ["Disabling GC permanently","A periodic mark-and-sweep audit comparing references from versions against refcounts","Doubling all refcounts","Deleting chunks older than one year"], 1, "An independent sweep from the source of truth, the versions, detects and repairs counter errors."),
    o(3, "Millions of clients reconnect after an outage. Which client behaviour most reduces the spike?", ["Retrying immediately in a tight loop","Exponential backoff with random jitter","Reconnecting exactly on the minute","Opening several connections per device"], 1, "Jitter spreads retries over time, so recovering servers are not overwhelmed in synchronized waves."),
    o(3, "What is a major consequence of end-to-end encryption for this service?", ["It removes the need for TLS","It makes conflict detection impossible","Uploads no longer need chunking","The server cannot dedup across users or generate previews and search indexes"], 3, "Without access to plaintext, server-side features that inspect content stop working."),
    o(3, "A user's access is revoked 2 minutes after they received a signed URL with a 5-minute expiry. What is true?", ["The URL can still fetch that chunk until it expires","The URL stops working immediately","The URL now returns a different file","The object storage deletes the chunk"], 0, "Signed URLs are bearer tokens validated by signature and expiry, which is why TTLs are kept short."),
    o(3, "How should storage quota be measured for a user?", ["Physical bytes after cross-user dedup","Number of files only","Logical bytes of the versions the user owns, reserved when the upload session opens","Bytes downloaded per month"], 2, "Logical bytes are predictable to users, and reserving quota up front prevents parallel uploads from overshooting."),
    o(2, "What is the size of a SHA-256 digest?", ["128 bits","160 bits","512 bits","256 bits"], 3, "SHA-256 produces a 256-bit, or 32-byte, digest."),
    o(2, "Which transport suits pushing sync hints to desktop clients?", ["SMTP email","A WebSocket or long-poll connection","FTP","Batch files over SFTP"], 1, "Persistent or long-poll connections let the server signal online devices with low latency."),
    o(2, "File-system watcher events can be dropped or coalesced. What should the desktop agent also do?", ["Periodically rescan and compare size, mtime or hashes","Trust events only","Disable sync when an event is missed","Upload every file hourly"], 0, "A rescan catches changes that lossy watcher APIs missed."),
    o(2, "A user tries to move a folder into one of its own subfolders. What should the metadata service do?", ["Allow it and fix it later","Duplicate the folder","Reject it after a cycle check inside the transaction","Move only the files and not the folders"], 2, "Allowing the move would create a cycle and detach the subtree from the root, so it must be rejected."),
  ],
};
export default bank;
